import{_ as e,c as a,o as r,a1 as n,eA as t}from"./chunks/framework.D7x6il7h.js";const u=JSON.parse('{"title":"Samspelet mellan klient och server.","description":"","frontmatter":{"outline":[1,6]},"headers":[],"relativePath":"web1/3-web/client-server.md","filePath":"web1/3-web/client-server.md"}'),l={name:"web1/3-web/client-server.md"},s=n('<h1 id="samspelet-mellan-klient-och-server" tabindex="-1">Samspelet mellan klient och server. <a class="header-anchor" href="#samspelet-mellan-klient-och-server" aria-label="Permalink to &quot;Samspelet mellan klient och server.&quot;">​</a></h1><p>När du surfar på internet eller använder en webbapp sker ett samspel mellan en klient (t.ex. din webbläsare) och en server (en dator som hanterar och skickar data).</p><p align="center"><img src="'+t+'" alt="klient-server-bild"></p><h2 id="vad-ar-en-klient" tabindex="-1">Vad är en klient? <a class="header-anchor" href="#vad-ar-en-klient" aria-label="Permalink to &quot;Vad är en klient?&quot;">​</a></h2><p>En klient är en enhet eller ett program som begär information från en server. Exempel på klienter är:</p><ul><li>Webbläsare (Google Chrome, Firefox, Safari)</li><li>Mobilappar</li><li>Andra program som hämtar data från internet</li></ul><p>När du skriver in en webbadress i webbläsaren skickas en begäran (request) till en server för att hämta webbplatsens innehåll.</p><br><h2 id="vad-ar-en-server" tabindex="-1">Vad är en server? <a class="header-anchor" href="#vad-ar-en-server" aria-label="Permalink to &quot;Vad är en server?&quot;">​</a></h2><p>En server är en kraftfull dator som lagrar och hanterar webbsidor, databaser och andra resurser. Servern tar emot begäran från klienten och skickar tillbaka rätt data som svar (response). Exempel på servrar är:</p><ul><li>Webbservrar (Apache, Nginx, IIS)</li><li>Databasservrar (MySQL, PostgreSQL)</li><li>API-servrar</li></ul><br><h2 id="hur-fungerar-samspelet" tabindex="-1">Hur fungerar samspelet? <a class="header-anchor" href="#hur-fungerar-samspelet" aria-label="Permalink to &quot;Hur fungerar samspelet?&quot;">​</a></h2><ol><li><span class="f">Klienten skickar en begäran</span> – När du besöker en webbplats, skickar webbläsaren en begäran till servern via HTTP eller HTTPS.</li><li><span class="f">Servern behandlar begäran</span> – Servern letar upp rätt resurs (t.ex. en HTML-sida eller en bild).</li><li><span class="f">Servern skickar ett svar</span> – Webbsidan skickas tillbaka till klienten, ofta i form av HTML, CSS och JavaScript.</li><li><span class="f">Klienten visar webbsidan</span> – Webbläsaren tolkar koden och visar sidan för användaren.</li></ol><br><h2 id="dynamiska-och-statiska-webbplatser" tabindex="-1">Dynamiska och statiska webbplatser <a class="header-anchor" href="#dynamiska-och-statiska-webbplatser" aria-label="Permalink to &quot;Dynamiska och statiska webbplatser&quot;">​</a></h2><ul><li><span class="f">Statisk webbplats</span> – Servern skickar färdiga HTML-filer utan förändring.</li><li><span class="f">Dynamisk webbplats</span> – Servern skapar innehållet vid varje begäran, ofta med hjälp av databaser och programmeringsspråk som PHP, Python eller Node.js.</li></ul><br><h2 id="ajax-och-realtidskommunikation" tabindex="-1">AJAX och realtidskommunikation <a class="header-anchor" href="#ajax-och-realtidskommunikation" aria-label="Permalink to &quot;AJAX och realtidskommunikation&quot;">​</a></h2><p>Med <span class="f">AJAX</span> (Asynchronous JavaScript and XML) kan klienten hämta data från servern utan att ladda om sidan. Exempel på detta är:</p><ul><li>Sökmotorers autoslutförande</li><li>Sociala medier-flöden</li><li>Chattfunktioner</li></ul><br><h2 id="sammanfattning" tabindex="-1">Sammanfattning <a class="header-anchor" href="#sammanfattning" aria-label="Permalink to &quot;Sammanfattning&quot;">​</a></h2><ul><li>Klienten (t.ex. en webbläsare) skickar begäran.</li><li>Servern tar emot och behandlar begäran.</li><li>Servern svarar med data (HTML, JSON, bilder, etc.).</li><li>Klienten visar informationen för användaren.</li></ul><p>Detta samspel är grunden för hur webben fungerar och är viktigt att förstå i webbutveckling!</p><br><p>😎 👊 👍</p>',27),i=[s];function o(d,b,c,p,h,m){return r(),a("div",null,i)}const v=e(l,[["render",o]]);export{u as __pageData,v as default};
